def test_router_two_phase_raw_generation(self):
    class FakeBackend:
        def __init__(self):
            self.calls = []

        def complete(
            self,
            system,
            user,
            *,
            json_mode=True,
        ):
            self.calls.append(json_mode)

            if json_mode:
                return json.dumps(
                    {
                        "tool": "append_file_raw",
                        "args": {
                            "path": "app.py",
                        },
                    }
                )

            return (
                'def hello():\n'
                '    print("hello")\n'
            )

    config = helix.HelixConfig(
        patchforge_cli="",
        max_steps=0,
        command_timeout_seconds=10,
        models={
            "main": helix.ModelSpec(
                provider="ollama",
                model="main",
            )
        },
    )

    router = helix.ModelRouter(config)
    fake = FakeBackend()
    router.backend = lambda role: fake

    payload = json.dumps(
        {
            "task": "Build app",
            "active_staged_file": "app.py",
            "staged_files": [
                {
                    "path": "app.py",
                    "characters": 0,
                }
            ],
            "recent_history": [],
        }
    )

    role, action = router.action_with_fallback(
        "main",
        "system",
        payload,
    )

    self.assertEqual(role, "main")
    self.assertEqual(
        action["tool"],
        "append_file_raw",
    )
    self.assertEqual(
        fake.calls,
        [True, False],
    )
    self.assertIn(
        'print("hello")',
        action["args"]["_raw_content"],
    )

def test_raw_generation_adds_final_newline(self):
    class FakeBackend:
        def complete(
            self,
            system,
            user,
            *,
            json_mode=True,
        ):
            return "print('hello')"

    config = helix.HelixConfig(
        patchforge_cli="",
        max_steps=0,
        command_timeout_seconds=10,
        models={
            "main": helix.ModelSpec(
                provider="ollama",
                model="main",
            )
        },
    )

    router = helix.ModelRouter(config)

    content = router._complete_raw_content(
        FakeBackend(),
        system="system",
        original_user=json.dumps(
            {
                "task": "test",
                "staged_files": [],
            }
        ),
        path="app.py",
    )

    self.assertEqual(
        content,
        "print('hello')\n",
    )
